        if kind == "nx":
            # NXDOMAIN 条目匹配任意 qtype：t 必须为 null。
            if qtype is not None:
                raise ConfigError("t must be null for nx")
        else:
            if not isinstance(qtype, int) or isinstance(qtype, bool):
                raise ConfigError("t must be int")
            if not 0 <= qtype <= 0xFFFF:
